package com.oguzguven.portfolio.message;
import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity @Table(name="contact_messages") public class ContactMessage{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(nullable=false,length=120)private String name;@Column(nullable=false,length=200)private String email;@Column(nullable=false,length=3000)private String message;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="is_read",nullable=false)private boolean read;protected ContactMessage(){}public ContactMessage(ContactMessageRequest r){name=r.name().trim();email=r.email().trim();message=r.message().trim();createdAt=Instant.now();read=false;}public void toggleRead(){read=!read;}public UUID getId(){return id;}public String getName(){return name;}public String getEmail(){return email;}public String getMessage(){return message;}public Instant getCreatedAt(){return createdAt;}public boolean isRead(){return read;}}
